const streams = () => {
	let out = "";
	let err = "";
	return {
		streams: {
			stdout: (text: string) => {
				out += text;
			},
			stderr: (text: string) => {
				err += text;
			},
		},
		get out() {
			return out;
		},
		get err() {
			return err;
		},
	};
};

